using Nutanix.SecSDK.Model.Security.V4.Report;

namespace CsharpSdkSample
{
  class Program
  {
    static void Main(string[] args) {
      // Configure the client
      Configuration _config = new Configuration
      {
        // UserName to connect to the cluster
        Username = "username",
        // Password(SecureString) to connect to the cluster 
        Password = Configuration.CreateSecurePassword("password"),
        // IPv4/IPv6 address or FQDN of the cluster
        Host = "localhost",
        // Port used for the connection. 
        Port = 9440,
        // Backoff period in seconds (exponential backoff: 2, 4, 8... seconds)
        BackOffPeriod = 2,
        // Max retry attempts while reconnecting on a loss of connection
        MaxRetryAttempts = 5
      };

      ApiClient client = new ApiClient(_config);

      VulnerabilitiesApi vulnerabilitiesApi = new VulnerabilitiesApi(client);

      int page = 0;
      int limit = 50;
      String filter = "string_sample_data";
      String orderby = "string_sample_data";
      String select = "string_sample_data";

        // Create request object with parameters
        var request = new ListVulnerabilitiesRequest {
            Page = page,
            Limit = limit,
            Filter = filter,
            Orderby = orderby,
            Select = select
        };
        try {
            ListVulnerabilitiesApiResponse listVulnerabilitiesApiResponse = vulnerabilitiesApi.ListVulnerabilities(request);
        } catch (ApiException ex) {
            Console.WriteLine(ex.Message);
        }
    }
  }
}
